Given a binary tree with n nodes, determine whether all the leaf nodes are at the same level or not. Return true if all leaf nodes are at the same level, and false otherwise.Examples:Input:Output: trueInput: Output: falseInput:Output: trueTry It YourselfTable of Content[Naive Approach] Recursive with Two Traversals - O(n) Time and O(n) Space[Expected Approach-1] Single Traversal using Leaf Level Tracking (DFS) - O(n) Time O(h) Space[Expected Approach-2] Level Order Traversal (BFS) - O(n) Time and O(n) Space[Naive Approach] Recursive with Two Traversals - O(n) Time and O(n) SpaceThe idea is to compare the max and min depths. The max depth represents the longest path from the root to any leaf, while the min depth represents the shortest path to a leaf. If both depths are equal, it means all leaf nodes are present at the same level; otherwise, they are at different levels.
            C++

    #include <iostream>
#include <climits>
using namespace std;


class Node {
public:
    int data;
    Node *left, *right;

    // Constructor
    Node(int item) {
        data = item;
        left = right = nullptr;
    }
};

// Function to find maximum depth (height) of the tree
int maxDist(Node* curr) {

    // Base case: if node is NULL, height is 0
    if (curr == nullptr) return 0;

    // Recursively find height of left and right subtree
    return 1 + max(maxDist(curr->left), maxDist(curr->right));
}

// Function to find minimum depth of the tree
int minDist(Node* curr) {

    if (curr == nullptr) return INT_MAX;

    // If it is a leaf node, minimum depth is 1
    if (curr->left == nullptr && curr->right == nullptr)
        return 1;

    // Recursively find minimum depth from left and right subtree
    return 1 + min(minDist(curr->left), minDist(curr->right));
}

// Function to check if all leaf nodes are at same level
bool check(Node *root) {

    int max_dist = maxDist(root);
    int min_dist = minDist(root);

    // If both are equal, all leaves are at same level
    if (max_dist == min_dist)
        return true;

    return false;
}

// Driver Code
int main() {
    // Constructing the tree:
    //        10
    //       /  \
    //     20    30
    //    /  \
    //  10   15

    Node* root = new Node(10);
    root->left = new Node(20);
    root->right = new Node(30);
    root->left->left = new Node(10);
    root->left->right = new Node(15);

    if (check(root))
        cout << "true\n";
    else
        cout << "false\n";

    return 0;
}


