            C++

    #include <iostream>
#include <queue>
using namespace std;

class Node
{
  public:
    int data;
    Node *left, *right;

    // Constructor
    Node(int item)
    {
        data = item;
        left = right = nullptr;
    }
};

/*You are required to complete this method*/
bool check(Node *root)
{

    // If tree is empty, return true
    if (!root)
        return true;

    queue<Node *> q;
    q.push(root);

    int flag = 0;

    // Level order traversal
    while (!q.empty())
    {

        int n = q.size();

        for (int i = 0; i < n; i++)
        {

            Node *temp = q.front();
            q.pop();

            // Push left and right children
            if (temp->left)
                q.push(temp->left);
            if (temp->right)
                q.push(temp->right);

            // If leaf node found, mark flag
            if (temp->left == nullptr && temp->right == nullptr)
                flag = 1;
        }

        // If leaf found and more nodes exist at next level
        if (flag && !q.empty())
            return false;
    }

    return true;
}

