function check(root) {

  // If tree is empty, return true
  if (!root)
    return true;

  let q = [];
  q.push(root);

  let flag = 0;

  // Level order traversal
  while (q.length > 0) {

    let n = q.length;

    for (let i = 0; i < n; i++) {

      let temp = q.shift();

      // Push left and right children
      if (temp.left)
        q.push(temp.left);
      if (temp.right)
        q.push(temp.right);

      // If leaf node found, mark flag
      if (temp.left == null && temp.right == null)
        flag = 1;
    }

    // If leaf found and more nodes exist at next level
    if (flag && q.length > 0)
      return false;
  }

  return true;
}

